-- SAP S/4HANA -> canonical PRICE_CONDITION (SAP_A). Generated by tools/build_silver_sql.py.
SELECT 'SAP_A' AS SOURCE_SLOT, 'SAP S/4HANA' AS SOURCE_SYSTEM, h.EBELN AS PO_NUMBER, TRY_TO_NUMBER(c.KPOSN)::STRING AS PO_ITEM, c.KSCHL AS CONDITION_TYPE,
  c.KBETR AS CONDITION_RATE, c.KWERT AS CONDITION_VALUE, c.WAERK AS CURRENCY
FROM {{ source('src_s4_a', 'prcd_elements') }} c JOIN {{ source('src_s4_a', 'ekko') }} h ON h.KNUMV = c.KNUMV
